{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://amap-spec/schemas/submit-request.schema.json",
  "title": "submit-request",
  "description": "agent -> runtime: an inert outbound request. amap-\
    spec v3.0.0 (spec/contract.md §3). Agent-authored: this document\
    's envelope stays CLOSED (additionalProperties:false) at every l\
    evel per §7's v3.0.0 asymmetry — an unrecognized member here is \
    a designed, legible `rejected` refusal, never a silent drop.",
  "type": "object",
  "required": ["contract_version", "req_id", "draft"],
  "additionalProperties": false,
  "properties": {
    "contract_version": { "const": "2" },
    "req_id": {
      "type": "string",
      "minLength": 1,
      "description": "monotonic per namespace; filename-safe (path a\
    uthority is the filename, not this field — §2, the filename-auth\
    ority-for-paths obligation).",
      "pattern": "^[A-Za-z0-9_][A-Za-z0-9_.-]*(?!\\n)$"
    },
    "agent_id": { "type": "string", "minLength": 1, "pattern": "^[^\\
    u0000-\u001f\u007f]*(?!\\n)$" },
    "ts": { "type": "string", "minLength": 1, "pattern": "^[^\u0000-\
    \u001f\u007f]*(?!\\n)$" },
    "in_reply_to": { "type": "string", "pattern": "^[^\u0000-\u001f\\
    u007f]*(?!\\n)$" },
    "draft": {
      "type": "object",
      "required": ["to", "subject", "body_text"],
      "additionalProperties": false,
      "properties": {
        "to": {
          "type": "array",
          "items": {
            "type": "string",
            "description": "one bare addr-spec per element (no displ\
    ay name, address list, quoted local part, comment, IP literal, o\
    r folding whitespace — deliberately narrower than RFC 5322: thos\
    e forms are exactly what make allowlist evaluation non-mechanica\
    l). EAI/SMTPUTF8 is out of scope at this version.",
            "pattern": "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9\
    .-]+(?!\\n)$"
          },
          "minItems": 1
        },
        "cc": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9\
    .-]+(?!\\n)$"
          }
        },
        "subject": { "type": "string", "pattern": "^[^\u0000-\u001f\\
    u007f]*(?!\\n)$" },
        "body_text": { "type": "string" },
        "reply_to_message_id": { "type": ["string", "null"], "patter\
    n": "^[^\u0000-\u001f\u007f]*(?!\\n)$" },
        "attachments": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["filename", "media_type", "size_bytes", "sh\
    a256"],
            "additionalProperties": false,
            "properties": {
              "filename":   { "type": "string", "minLength": 1, "pat\
    tern": "^[^\u0000-\u001f\u007f]*(?!\\n)$" },
              "media_type": { "type": "string", "minLength": 1, "pat\
    tern": "^[^\u0000-\u001f\u007f]*(?!\\n)$" },
              "size_bytes": { "type": "integer", "minimum": 0 },
              "sha256":     { "type": "string", "pattern": "^[a-f0-9\
    ]{64}(?!\\n)$" }
            }
          }
        }
      }
    }
  }
}

NOTE: '\' line wrapping per RFC 8792

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://amap-spec/schemas/result.schema.json",
  "title": "result",
  "description": "runtime -> agent: verdict for a submit-request. am\
    ap-spec v3.0.0 (spec/contract.md §4). Runtime-authored: this doc\
    ument's envelope is OPEN (no additionalProperties:false) at ever\
    y level per §7's v3.0.0 tolerance rule — a consumer MUST ignore \
    members it does not recognize; emitting an unrecognized member r\
    emains producer non-conformance.",
  "type": "object",
  "required": ["contract_version", "req_id", "outcome"],
  "properties": {
    "contract_version": { "const": "2" },
    "req_id": { "type": "string", "minLength": 1 },
    "outcome": {
      "type": "string",
      "enum": ["accepted", "queued_for_human", "rejected"]
    },
    "detail": { "type": ["string", "null"] },
    "reason_code": { "type": "string", "minLength": 1 },
    "ts": { "type": "string", "minLength": 1 },
    "recipients": { "type": "array", "items": { "type": "string" } },
    "message_id": { "type": ["string", "null"] },
    "job_id": { "type": ["string", "null"] },
    "attestation": {
      "type": "object",
      "required": ["form"],
      "properties": {
        "form":   { "type": "string", "enum": ["self-stamp", "verifi\
    able"] },
        "token":  { "type": "string", "minLength": 1 },
        "claims": { "type": "object" }
      }
    },
    "attachments": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["index", "outcome"],
        "properties": {
          "index":   { "type": "integer", "minimum": 0 },
          "outcome": { "type": "string",
                       "enum": ["accepted", "dlp_held", "rejected_ty\
    pe", "too_large"] },
          "detail":  { "type": ["string", "null"] }
        }
      }
    }
  }
}

